# Find the weight class containing 55 kg, then return the lowest amount
# lifted in that class.
weight_classes = df['Weight Class'].dropna().unique()
target_class = next(
    (wc for wc in weight_classes
     if int(wc.split()[0]) >= 55),
    None
)

if target_class is None:
    return None

df.columns = [
    'rank', 'personName', 'age', 'finalWorth', 'category', 'source',
    'country', 'state', 'city', 'organization', 'selfMade', 'gender',
    'birthDate', 'title', 'philanthropyScore', 'bio', 'about'
]

return df['age'].min()

def answer(df: pd.DataFrame):
    salary_col = 'Gross annual salary (in euros) 💸'
    return df[salary_col].mean()

