def answer(df: pd.DataFrame):
    df.columns = ['Lifter Name', 'Age', 'Weight Class', 'Lift Type', 'Amount Lifted (kg)']

    # A 55 kg lifter participates in the 59 kg weight class.
    return df.loc[df['Weight Class'] == '59 kg', 'Amount Lifted (kg)'].min()

